INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-ii-japan', 'GAMEBOY', 'Mickey Mouse II (Japan)', '1992', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling puzzle platformer.', 'Rescue your friends from the castle.', 'Mickey''s Crazy Castle 2 (Japan).', 'Known as "The Real Ghostbusters" or "Garfield Labyrinth" in other regions, this version features Mickey solving puzzles in a multi-floor tower.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-iv-japan', 'GAMEBOY', 'Mickey Mouse IV (Japan)', '1993', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling puzzle platformer.', 'Stop the ghost and save the day.', 'Mickey''s Crazy Castle 3 (Japan).', 'A continuation of the puzzle-platforming formula with improved graphics and larger levels where Mickey must outsmart Disney villains.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickey-mouse-v-japan', 'GAMEBOY', 'Mickey Mouse V (Japan)', '1994', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling puzzle platformer.', 'Navigate through the magical world.', 'Mickey''s Crazy Castle 4 (Japan).', 'The final 8-bit entry of the series in Japan, offering refined puzzles and more interactive environmental elements for Mickey to master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-chase-europe', 'GAMEBOY', 'Mickey''s Chase (Europe)', '1991', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling platformer.', 'Chase Pluto and recover the magic hat.', 'Mickey''s Chase (Europe).', 'A fast-paced platformer where Mickey must run through various Disney-themed levels to catch Pluto, who is being chased by Pete.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-chase-japan', 'GAMEBOY', 'Mickey''s Chase (Japan)', '1991', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling platformer.', 'Chase Pluto and recover the magic hat.', 'Mickey''s Chase (Japan).', 'The Japanese release of the chase adventure, featuring smooth animations and iconic Disney characters in a portable format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-chase-usa', 'GAMEBOY', 'Mickey''s Chase (USA)', '1991', 'Platformer', 'Kemco', '1', 'Cartoon', 'Side-scrolling platformer.', 'Chase Pluto and recover the magic hat.', 'Mickey''s Chase (USA).', 'The North American version, known for its accessible difficulty and faithful recreation of Mickey''s cartoon aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-ultimate-challenge-usa-europe', 'GAMEBOY', 'Mickey''s Ultimate Challenge (USA, Europe)', '1994', 'Puzzle', 'Electronic Arts', '1', 'Cartoon', 'Mini-game collection / Puzzle.', 'Solve the mystery of the strange book.', 'Mickey''s Ultimate Challenge.', 'Mickey (or Minnie) travels through a storybook world, completing logic puzzles and memory games to reach the castle in the clouds.');
