INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('midori-no-makibaou-japan', 'GAMEBOY', 'Midori no Makibaou (Japan)', '1996', 'Sports', 'Jaleco', '1', 'Horse Racing', 'Horse racing / Mini-games.', 'Train your donkey-like horse to win.', 'Anime-based racing sim.', 'Based on the humorous manga, players manage Makibaoh''s training and participate in races and wacky mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mighty-morphin-power-rangers---the-movie-usa-europe', 'GAMEBOY', 'Mighty Morphin Power Rangers - The Movie (USA, Europe)', '1995', 'Action-Platformer', 'Natsume', '1', 'Superhero', 'Side-scrolling beat ''em up.', 'Stop Ivan Ooze and save Angel Grove.', 'Power Rangers Movie action.', 'Choose your favorite Ranger and fight through stages based on the 1995 film, ending with massive Megazord boss battles.');
