INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('millipede-&-centipede-usa-europe', 'GAMEBOY', 'Millipede & Centipede (USA, Europe)', '1995', 'Shooter', 'Atari', '2', 'Arcade', 'Fixed-screen shooter.', 'Destroy the segments of the incoming insects.', 'Atari arcade duo.', 'A perfect portable compilation of two arcade hits, requiring fast reflexes to blast descending millipedes and centipedes.');
